        #"{"request_id":"omp_session_semantic:dc171b343abad662c2ef9159f474fd9821b0a9aa451eaaee64634a75ef6007d8","semantic_id":"omp_session_semantic:dc171b343abad662c2ef9159f474fd9821b0a9aa451eaaee64634a75ef6007d8","has_entry_id":false,"provider_id":"p","model":"m","request_model":"m","input":9,"output":0,"cache_read":0,"cache_write":0,"latency_ms":0,"status_code":200,"error_message":null,"created_at":1793343600,"reported":null}"#,
        #"{"request_id":"omp_session:7a7f558e81173c53cf7b0c13122041b8ac72ef98ba170f0c7f1ba03b614e75c8","semantic_id":"omp_session_semantic:c73417cf7c6e9ad8381efba2630e8ca87f051d5b2095a500e81bad3fca4cf838","has_entry_id":true,"provider_id":"p","model":"m","request_model":"m","input":0,"output":0,"cache_read":0,"cache_write":0,"latency_ms":0,"status_code":500,"error_message":"Oh My Pi request failed","created_at":1793347200,"reported":null}"#,
    ]

    /// (JSON 里的写法, serde_json 的输出)
    static let floats: [(String, String)] = [
        (#"1.0"#, #"1.0"#),
        (#"0.3"#, #"0.3"#),
        (#"100.0"#, #"100.0"#),
        (#"1e2"#, #"100.0"#),
        (#"5E-7"#, #"5e-7"#),
        (#"1e-7"#, #"1e-7"#),
        (#"0.00001"#, #"0.00001"#),
        (#"0.000001"#, #"1e-6"#),
        (#"0.0000846"#, #"0.0000846"#),
        (#"0.000014592"#, #"0.000014592"#),
        (#"6744.172099999996"#, #"6744.172099999996"#),
        (#"1e15"#, #"1000000000000000.0"#),
        (#"1e16"#, #"1e+16"#),
        (#"123456789012345680.0"#, #"1.2345678901234568e+17"#),
        (#"1.5e300"#, #"1.5e+300"#),
        (#"2.2250738585072014e-308"#, #"2.2250738585072014e-308"#),
        (#"5e-324"#, #"5e-324"#),
        (#"0.1"#, #"0.1"#),
        (#"1.7976931348623157e308"#, #"1.7976931348623157e+308"#),
        (#"-0.0"#, #"-0.0"#),
        (#"-1.5"#, #"-1.5"#),
        (#"12.34"#, #"12.34"#),
        (#"0.001234"#, #"0.001234"#),
        (#"1e21"#, #"1e+21"#),
        (#"1e-5"#, #"0.00001"#),
        (#"123456.0"#, #"123456.0"#),
        (#"1e-4"#, #"0.0001"#),
        (#"3.0e-5"#, #"0.00003"#),
        (#"25.0e-1"#, #"2.5"#),
    ]

    private func json(_ s: String) -> NSDictionary {
        (try? JSONSerialization.jsonObject(with: Data(s.utf8))) as? NSDictionary ?? [:]
    }

    /// 负责杀的变异体：种类判定、token / 成本 / 时间戳 / 耗时 / 状态码 / 标签截断 / 身份哈希里任何一处
    /// 与上游不一致（26 条样例逐字段比对）。
    func testRecordsMatchUpstreamGold() throws {
        for (i, (line, expected)) in zip(Self.fixture, Self.gold).enumerated() {
            let record = OmpUsage.record(from: json(line), sessionId: "sess-1",
                                         sessionTimestamp: 1_700_000_000, fileTimestamp: 1_600_000_000)
            guard let gold = try JSONSerialization.jsonObject(
                    with: Data(expected.utf8), options: .fragmentsAllowed) as? NSDictionary else {
                XCTAssertNil(record, "#\(i) 上游不计入")
                continue
            }
            guard let r = record else { XCTFail("#\(i) 上游计入、这里没有"); continue }
            XCTAssertEqual(r.requestId, gold["request_id"] as? String, "#\(i) request_id")
            XCTAssertEqual(r.semanticId, gold["semantic_id"] as? String, "#\(i) semantic_id")
            XCTAssertEqual(r.hasEntryId, gold["has_entry_id"] as? Bool, "#\(i) has_entry_id")
            XCTAssertEqual(r.providerId, gold["provider_id"] as? String, "#\(i) provider_id")
            XCTAssertEqual(r.model, gold["model"] as? String, "#\(i) model")
            XCTAssertEqual(r.requestModel, gold["request_model"] as? String, "#\(i) request_model")
            XCTAssertEqual(r.input, (gold["input"] as? NSNumber)?.int64Value, "#\(i) input")
            XCTAssertEqual(r.output, (gold["output"] as? NSNumber)?.int64Value, "#\(i) output")
            XCTAssertEqual(r.cacheRead, (gold["cache_read"] as? NSNumber)?.int64Value, "#\(i) cache_read")
            XCTAssertEqual(r.cacheWrite, (gold["cache_write"] as? NSNumber)?.int64Value, "#\(i) cache_write")
            XCTAssertEqual(r.latencyMs, (gold["latency_ms"] as? NSNumber)?.int64Value, "#\(i) latency_ms")
            XCTAssertEqual(r.statusCode, (gold["status_code"] as? NSNumber)?.int64Value, "#\(i) status_code")
            XCTAssertEqual(r.errorMessage, gold["error_message"] as? String, "#\(i) error_message")
            XCTAssertEqual(r.createdAt, (gold["created_at"] as? NSNumber)?.int64Value, "#\(i) created_at")
            if let reported = gold["reported"] as? [String] {
                guard let c = r.costs.reported else { XCTFail("#\(i) 上游有自报成本"); continue }
                for (got, want) in zip([c.input, c.output, c.cacheRead, c.cacheWrite, c.total], reported) {
                    let w = Double(want) ?? .nan
                    XCTAssertEqual(got, w, accuracy: max(abs(w), 1e-30) * 1e-12, "#\(i) cost \(want)")
                }
            } else {
                XCTAssertNil(r.costs.reported, "#\(i) 上游没有自报成本（交给查价）")
            }
        }
    }

    /// 负责杀的变异体：RyuFormat 的四种排版（整数值、普通小数、前导零小数、科学计数）任一分界或指数符号写错。
    func testFloatFormattingMatchesSerdeJson() {
        for (literal, expected) in Self.floats {
            guard let d = Double(literal) else { XCTFail(literal); continue }
            XCTAssertEqual(RyuFormat.string(d), expected, literal)
        }
    }

    /// 已知差异的锁：serde_json 默认的浮点解析会二次舍入（9007199254740993.0 → …994），
    /// JSONSerialization / Double 就近舍入到 …992。这条断言只记录现状，提醒上游若开 float_roundtrip 就能对上。
    func testKnownSerdeParseDifferenceIsDocumented() {
        XCTAssertEqual(RyuFormat.string(Double("9007199254740993.0")!), "9007199254740992.0")
    }

    /// 负责杀的变异体：投影的子会话链接收集漏掉嵌套数组 / 非 toolResult 也收集。
    func testProjectionSessionFilesCollectsNestedLinksOnlyForToolResults() {
        let tool = json(#"{"type":"message","message":{"role":"toolResult","usage":{"input":1},"details":{"a":[{"sessionFile":"/x/1.jsonl"},{"b":{"sessionFile":"/x/2.jsonl"}}],"sessionFile":7}}}"#)
        XCTAssertEqual(Set(OmpUsage.projectionSessionFiles(tool)), ["/x/1.jsonl", "/x/2.jsonl"])
        let assistant = json(#"{"type":"message","message":{"role":"assistant","usage":{"input":1},"details":{"sessionFile":"/x/1.jsonl"}}}"#)
        XCTAssertEqual(OmpUsage.projectionSessionFiles(assistant), [])
        let noUsage = json(#"{"type":"message","message":{"role":"toolResult","details":{"sessionFile":"/x/1.jsonl"}}}"#)
        XCTAssertEqual(OmpUsage.projectionSessionFiles(noUsage), [])
    }
}
